const lockLiveRedemption = `-- name: LockLiveRedemption :one
SELECT r.id, r.coupon_id, r.promotion_code_id, COALESCE(p.restore_on_reversal, false)::boolean AS restore
FROM coupon_redemptions r LEFT JOIN promotion_codes p ON p.tenant_id = r.tenant_id AND p.id = r.promotion_code_id
WHERE r.tenant_id = app_tenant_id() AND r.target_kind = $1 AND r.target_id = $2 AND r.reversed_at IS NULL
FOR UPDATE OF r
`

type LockLiveRedemptionParams struct {
	TargetKind string
	TargetID   uuid.UUID
}

type LockLiveRedemptionRow struct {
	ID              uuid.UUID
	CouponID        uuid.UUID
	PromotionCodeID *uuid.UUID
	Restore         bool
}

// The redemption of a purchase, with whether its code gives the place back, locked for the reversal.
func (q *Queries) LockLiveRedemption(ctx context.Context, arg LockLiveRedemptionParams) (LockLiveRedemptionRow, error) {
	row := q.db.QueryRow(ctx, lockLiveRedemption, arg.TargetKind, arg.TargetID)
	var i LockLiveRedemptionRow
	err := row.Scan(
		&i.ID,
		&i.CouponID,
		&i.PromotionCodeID,
		&i.Restore,
	)
	return i, err
}

const lockPendingCustomerCoupon = `-- name: LockPendingCustomerCoupon :one
SELECT cc.id, cc.coupon_id FROM customer_coupons cc JOIN coupons c ON c.tenant_id = cc.tenant_id AND c.id = cc.coupon_id
WHERE cc.tenant_id = app_tenant_id() AND cc.customer_id = $1 AND cc.consumed_at IS NULL AND c.active
  AND (c.expires_at IS NULL OR c.expires_at > $2::timestamptz) AND (c.max_redemptions IS NULL OR c.redeemed < c.max_redemptions)
ORDER BY cc.created_at, cc.id LIMIT 1
FOR UPDATE OF cc SKIP LOCKED
`

type LockPendingCustomerCouponParams struct {
	CustomerID uuid.UUID
	Now        time.Time
}

type LockPendingCustomerCouponRow struct {
	ID       uuid.UUID
	CouponID uuid.UUID
}

// The oldest coupon waiting for the customer that still works, locked so two checkouts do not both use it.
func (q *Queries) LockPendingCustomerCoupon(ctx context.Context, arg LockPendingCustomerCouponParams) (LockPendingCustomerCouponRow, error) {
	row := q.db.QueryRow(ctx, lockPendingCustomerCoupon, arg.CustomerID, arg.Now)
	var i LockPendingCustomerCouponRow
	err := row.Scan(&i.ID, &i.CouponID)
	return i, err
}

