const markRedemptionReversed = `-- name: MarkRedemptionReversed :exec
UPDATE coupon_redemptions SET reversed_at = $1::timestamptz, slot_returned = $2::boolean WHERE tenant_id = app_tenant_id() AND id = $3
`

type MarkRedemptionReversedParams struct {
	Now          time.Time
	SlotReturned bool
	ID           uuid.UUID
}

func (q *Queries) MarkRedemptionReversed(ctx context.Context, arg MarkRedemptionReversedParams) error {
	_, err := q.db.Exec(ctx, markRedemptionReversed, arg.Now, arg.SlotReturned, arg.ID)
	return err
}

const returnCouponSlot = `-- name: ReturnCouponSlot :exec
UPDATE coupons SET redeemed = redeemed - 1 WHERE tenant_id = app_tenant_id() AND id = $1 AND redeemed > 0
`

func (q *Queries) ReturnCouponSlot(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, returnCouponSlot, id)
	return err
}

const returnPromotionCodeSlot = `-- name: ReturnPromotionCodeSlot :exec
UPDATE promotion_codes SET redeemed = redeemed - 1 WHERE tenant_id = app_tenant_id() AND id = $1 AND redeemed > 0
`

func (q *Queries) ReturnPromotionCodeSlot(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, returnPromotionCodeSlot, id)
	return err
}

